#!/bin/sh
# Oracle solution (FR-40). Generated by eval-harvest emit; do not edit by hand.
#
# Verifier/reference-only: this file, and the reference findings it carries, are never placed where
# the evaluated agent can read them. Harbor's oracle agent uploads solution/ to /solution and runs
# this script (agents/oracle.py:105-151). It submits the reference findings as if it were the agent,
# so the reward stack can be proven to respond to a known-good submission (a non-zero coverage_all).
#
# The findings are inlined at emit time rather than read from tests/oracle.json, because in separate
# verifier mode Harbor builds the verifier image from tests/ and uploads nothing at runtime
# (tech-plan.md:489) — so /tests/ does not exist in the agent environment, which is where this script
# runs. Reading it there failed FileNotFoundError in every trial on 2026-09-07, and the known-good
# submission was never made (R-3).
set -eu

# The submission is written under the artifacts convention dir (/logs/artifacts), not /logs/agent,
# because that is the one channel Harbor carries from the agent environment into the separate verifier
# (trial.py:706-712 uploads only artifacts_dir; the convention entry re-materializes /logs/artifacts in
# the verifier). A file under /logs/agent never reaches score.py, which then grades an empty submission
# (R-8). score.py's _DEFAULT_AGENT_FINDINGS and instruction.md name the same path.
findings_path="${EVAL_HARVEST_AGENT_FINDINGS:-/logs/artifacts/findings.json}"
mkdir -p "$(dirname "$findings_path")"

# The submission: one record per (finding, location) pair — statement, path, line, and severity, the
# four fields score.py consumes. Built at emit time from the same findings tests/oracle.json is
# serialized from, so the two cannot disagree. The payload is a single-line JSON array inside a quoted
# heredoc: the quotes stop the shell expanding it, and json.dumps escapes every newline, so no payload
# byte can close the heredoc early.
python3 - "$findings_path" <<'PY'
import json
import sys

submission = []
with open(sys.argv[1], "w", encoding="utf-8") as handle:
    json.dump(submission, handle)
PY
